pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {
        EscalationManagerInterface_Proxy.AssertionPolicy memory policy;

        bytes memory data = abi.encodeWithSelector(c.getAssertionPolicy.selector, assertionId);
        (bool ok, bytes memory returned) = address(c).staticcall(data);
        assertTrue(ok);

        (bool blockAssertion, , , ) = abi.decode(returned, (bool, bool, bool, bool));
        assertTrue(blockAssertion == false);
    }
}

interface EscalationManagerInterface_Proxy {
    struct AssertionPolicy {
        bool blockAssertion;
        bool arbitrateViaEscalationManager;
        bool discardOracle;
        bool validateDisputers;
    }
}
